-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the wellcorrelation capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: some graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: some graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update moves it to a
--   case of its own.
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- wellcorrelation / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '3a2dc1bcd2bd85910cfde760e7bcda89' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb then 'old'
              when md5(prompt) = 'b4026fc2b6e46a77a171906c69e1d6f4' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/beginner matches neither its published form (prompt md5 3a2dc1bcd2bd85910cfde760e7bcda89) nor its W1 form (prompt md5 b4026fc2b6e46a77a171906c69e1d6f4), with the fields this file was generated against';
  end if;

  -- wellcorrelation / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'ff93446f08c084743566694f406cf9d2' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb then 'old'
              when md5(prompt) = '06340559816bd341fd61af8b492e735a' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/intermediate matches neither its published form (prompt md5 ff93446f08c084743566694f406cf9d2) nor its W1 form (prompt md5 06340559816bd341fd61af8b492e735a), with the fields this file was generated against';
  end if;

  -- wellcorrelation / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'f0eed8034285b0ec685c060692d84449' and fields = '[{"key": "a_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_A to TOP_B interval", "expected": 141}, {"key": "sand_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_SAND to TOP_B interval", "expected": 92}, {"key": "w4_topb_layercake", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, layer-cake estimate", "expected": 1671}, {"key": "w4_topb_from_sand", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, from TOP_SAND", "expected": 1682}, {"key": "prediction_spread", "tol": 0.01, "unit": "m", "label": "Spread between the two estimates", "expected": 11}, {"key": "topb_relief", "tol": 0.01, "unit": "m", "label": "TOP_B structural relief where it is drilled", "expected": 34}]'::jsonb then 'old'
              when md5(prompt) = '2038aeb4f2423dab918bd6668bc91cc3' and fields = '[{"key": "a_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_A to TOP_B interval", "expected": 141}, {"key": "sand_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_SAND to TOP_B interval", "expected": 92}, {"key": "w4_topb_layercake", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, layer-cake estimate", "expected": 1671}, {"key": "w4_topb_from_sand", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, from TOP_SAND", "expected": 1682}, {"key": "prediction_spread", "tol": 0.01, "unit": "m", "label": "Spread between the two estimates", "expected": 11}, {"key": "topb_relief", "tol": 0.01, "unit": "m", "label": "TOP_B structural relief where it is drilled", "expected": 34}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/advanced matches neither its published form (prompt md5 f0eed8034285b0ec685c060692d84449) nor its W1 form (prompt md5 2038aeb4f2423dab918bd6668bc91cc3), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book wellcorrelation: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book wellcorrelation refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update moves it to a case of its own. Flatten the section on TOP_SAND at a 1500 m datum and read the panel: report the flattening shifts, the SAND zone thickness, displayed depths under the datum, the structural relief on TOP_SAND, and Ekene-3''s TOP_B displayed depth once the section is re-flattened on BASE_SAND at a 1560 m datum.',
           fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb
     where app_slug = 'wellcorrelation' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'b4026fc2b6e46a77a171906c69e1d6f4' and fields = '[{"key": "w2_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: flattening shift", "expected": -65}, {"key": "w3_sand_thickness_m", "tol": 0.01, "unit": "m", "label": "Ekene-3: SAND zone thickness", "expected": 29}, {"key": "w4_base_sand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: BASE_SAND displayed depth (flattened)", "expected": 1525}, {"key": "sand_relief_m", "tol": 0.01, "unit": "m", "label": "TOP_SAND structural relief across the section", "expected": 49}, {"key": "w3_top_b_displayed_base_1560_m", "tol": 0.5, "unit": "m", "label": "Ekene-3: TOP_B displayed depth, flattened on BASE_SAND at 1560 m", "expected": 1618.0}, {"key": "w1_top_b_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-1: TOP_B displayed depth (flattened)", "expected": 1592}]'::jsonb) from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update moves it to a case of its own. Flatten the section on TOP_A at a 1450 m datum and study the A-to-SAND interval: report the Ekene-4 shift, the displayed TOP_SAND in Ekene-2, the interval thickness in Ekene-4, the growth range across the section, the shallowest displayed depth once the section is re-flattened on TOP_SAND at a 1480 m datum, and the displayed depth span of the section back on the TOP_A datum.',
           fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb
     where app_slug = 'wellcorrelation' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '06340559816bd341fd61af8b492e735a' and fields = '[{"key": "w4_shift_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: flattening shift", "expected": -80}, {"key": "w2_topsand_displayed_m", "tol": 0.01, "unit": "m", "label": "Ekene-2: TOP_SAND displayed depth", "expected": 1503}, {"key": "a_to_sand_w4_m", "tol": 0.01, "unit": "m", "label": "Ekene-4: TOP_A→TOP_SAND interval", "expected": 60}, {"key": "growth_range_m", "tol": 0.01, "unit": "m", "label": "A-to-SAND growth range (max − min)", "expected": 14}, {"key": "shallowest_displayed_sand_1480_m", "tol": 0.5, "unit": "m", "label": "Shallowest displayed depth, flattened on TOP_SAND at 1480 m", "expected": 1420.0}, {"key": "displayed_span_m", "tol": 0.01, "unit": "m", "label": "Displayed depth span of the section", "expected": 150}]'::jsonb) from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Ekene-4 TDs above TOP_B. Predict the missing pick two ways from the three wells that carry it: project the mean TOP_A to TOP_B interval down from TOP_A (the layer-cake estimate), and the mean TOP_SAND to TOP_B interval down from TOP_SAND. Report both predictions, their spread (that is the growth uncertainty), the two mean intervals, and the structural relief of TOP_B where it is drilled.',
           fields = '[{"key": "a_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_A to TOP_B interval", "expected": 141}, {"key": "sand_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_SAND to TOP_B interval", "expected": 92}, {"key": "w4_topb_layercake", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, layer-cake estimate", "expected": 1671}, {"key": "w4_topb_from_sand", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, from TOP_SAND", "expected": 1682}, {"key": "prediction_spread", "tol": 0.01, "unit": "m", "label": "Spread between the two estimates", "expected": 11}, {"key": "topb_relief", "tol": 0.01, "unit": "m", "label": "TOP_B structural relief where it is drilled", "expected": 34}]'::jsonb
     where app_slug = 'wellcorrelation' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '2038aeb4f2423dab918bd6668bc91cc3' and fields = '[{"key": "a_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_A to TOP_B interval", "expected": 141}, {"key": "sand_to_b_mean", "tol": 0.01, "unit": "m", "label": "Mean TOP_SAND to TOP_B interval", "expected": 92}, {"key": "w4_topb_layercake", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, layer-cake estimate", "expected": 1671}, {"key": "w4_topb_from_sand", "tol": 0.01, "unit": "m", "label": "Ekene-4 TOP_B, from TOP_SAND", "expected": 1682}, {"key": "prediction_spread", "tol": 0.01, "unit": "m", "label": "Spread between the two estimates", "expected": 11}, {"key": "topb_relief", "tol": 0.01, "unit": "m", "label": "TOP_B structural relief where it is drilled", "expected": 34}]'::jsonb) from public.academy_capstones where app_slug = 'wellcorrelation' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book wellcorrelation refused: wellcorrelation/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book wellcorrelation: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
